<script>document.addEventListener('DOMContentLoaded',()=>{const list=document.querySelector('#detail-list'),tpl=document.querySelector('#detail-template'),type=document.querySelector('#transmittal-type');const sync=()=>{document.querySelectorAll('.catalog-picker').forEach(picker=>picker.hidden=type.value==='Incoming');};const renumber=()=>{[...list.children].forEach((row,i)=>{if(!row.querySelector('.row-tools')){const remove=row.querySelector('.remove-row'),tools=document.createElement('div'),duplicate=document.createElement('button');tools.className='row-tools';duplicate.type='button';duplicate.className='duplicate-row';duplicate.title='Duplicate row';duplicate.textContent='Duplicate';remove.replaceWith(tools);tools.append(duplicate,remove);}row.querySelector('.row-number').textContent=i+1;row.querySelectorAll('[data-name]').forEach(el=>el.name=`details[${i}][${el.dataset.name}]`);const picker=row.querySelector('[data-picker]'),hidden=row.querySelector('[data-name="item_id"]');if(picker){picker.setAttribute('list',`catalog-options-${i}`);const oldList=picker.parentElement.querySelector('datalist');if(oldList)oldList.id=`catalog-options-${i}`;picker.oninput=()=>{const option=[...oldList.options].find(opt=>opt.value===picker.value);if(!option){hidden.value='';return;}hidden.value=option.dataset.id||'';row.querySelector('[data-name="item_desc"]').value=option.dataset.desc||'';row.querySelector('[data-name="item_unit"]').value=option.dataset.unit||'';row.querySelector('[data-name="item_serial_no"]').value=option.dataset.serial||'';row.querySelector('[data-name="par_no"]').value=option.dataset.par||'';};}});sync();};document.querySelector('#add-detail').onclick=()=>{list.append(tpl.content.cloneNode(true));renumber()};list.addEventListener('click',e=>{const row=e.target.closest('.detail-row');if(e.target.classList.contains('duplicate-row')){const clone=row.cloneNode(true);clone.querySelector('[data-picker]').value='';clone.querySelector('[data-name="item_id"]').value='';clone.querySelector('[data-name="item_qty"]').value='1';clone.querySelector('[data-name="item_serial_no"]').value='';clone.querySelector('[data-name="par_no"]').value='';const file=clone.querySelector('[data-name="attachment"]');if(file)file.value='';row.after(clone);renumber();}if(e.target.classList.contains('remove-row')&&list.children.length>1){row.remove();renumber();}});type.onchange=sync;renumber()});</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const units=['pc','unit','set','box','copy','pack','meter','lot'],list=document.querySelector('#detail-list');const apply=()=>document.querySelectorAll('.detail-row').forEach(row=>{const qty=row.querySelector('[data-name="item_qty"]');if(qty){qty.value=qty.value||'1';qty.readOnly=false;}const unit=row.querySelector('[data-name="item_unit"]');if(unit&&unit.tagName==='INPUT'){const select=document.createElement('select');select.dataset.name='item_unit';select.name=unit.name;select.innerHTML='<option value="">Select unit</option>'+units.map(value=>`<option value="${value}">${value.toUpperCase()}</option>`).join('');select.value=unit.value||'';unit.replaceWith(select);}});apply();new MutationObserver(apply).observe(list,{childList:true,subtree:true});});</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const type=document.querySelector('#transmittal-type'),destination=document.querySelector('input[name="destination"]');if(!type||!destination)return;const label=destination.closest('label');const updateLabel=()=>{label.firstChild.textContent=(type.value==='Incoming'?'Source':'Destination')+' *';};updateLabel();type.addEventListener('change',updateLabel);});</script>
